const c={movie:t=>[`https://vidsrc.pro/embed/movie/${t}`,`https://2embed.to/embed/tmdb/movie?id=${t}`,`https://embed.su/embed/movie/${t}`,`https://multiembed.ru/movie/${t}`,`https://vidbinge.com/embed/movie/${t}`],tv:(t,e,o)=>[`https://vidsrc.pro/embed/tv/${t}/${e}/${o}`,`https://2embed.to/embed/tmdb/tv?id=${t}&s=${e}&e=${o}`,`https://embed.su/embed/tv/${t}/${e}/${o}`,`https://multiembed.ru/tv/${t}/${e}/${o}`,`https://vidbinge.com/embed/tv/${t}/${e}/${o}`]},l=async(t,e,o,s)=>{const r=t==="movie"?c.movie(e):c.tv(e,o,s);console.log(`🔍 جاري تجربة ${r.length} مصدراً للعنصر ${t} ${e}...`);for(const m of r)try{const $=new AbortController,b=setTimeout(()=>$.abort(),5e3);return await fetch(m,{method:"HEAD",mode:"no-cors",signal:$.signal}),clearTimeout(b),console.log(`✅ تم العثور على مصدر يعمل: ${m}`),m}catch{console.log(`❌ المصدر لا يعمل: ${m}`)}return console.warn("⚠️ لم يتم العثور على مصدر يعمل، سيتم استخدام أول مصدر كحل احتياطي."),r[0]||null};export{l as g};
